('퇴학', '장기 미출석', '2025-02-01 00:00:00', 400, 1);

DELIMITER $$
CREATE PROCEDURE InsertTuitionData()
BEGIN
    DECLARE i INT DEFAULT 1;
    
    -- 1~350번 학생 (5번 납부)
    WHILE i <= 350 DO
        SET i = i + 1;
    END WHILE;

    -- 351~400번 학생 (2번 납부)
    SET i = 351;
    WHILE i <= 400 DO
        SET i = i + 1;
    END WHILE;
END $$
DELIMITER ;
-- 실행
CALL InsertTuitionData();
-- 실행 후 프로시저 삭제 (깔끔하게)
DROP PROCEDURE InsertTuitionData;

