UPDATE student
SET student_email = CONCAT(SUBSTRING_INDEX(student_email, '@', 1), '@goodee.ac.kr')
WHERE student_email LIKE '%@kakao.com';

-- lecture_history 더미
DELIMITER $$

DROP PROCEDURE IF EXISTS insert_lecture_history_dummy_v1 $$
CREATE PROCEDURE insert_lecture_history_dummy_v1()
BEGIN
    DECLARE v_student_cnt INT DEFAULT 0;
    DECLARE v_term_cnt INT DEFAULT 0;

    DECLARE i INT DEFAULT 1;
    DECLARE j INT DEFAULT 1;

    DECLARE v_student_id INT;
    DECLARE v_student_major_id INT;

    DECLARE v_has_student_major INT DEFAULT 0;

    DECLARE v_cutoff_at DATETIME;

    DECLARE v_year INT;
    DECLARE v_sem INT;
    DECLARE v_start_date DATE;

    DECLARE v_credit_sum INT;
    DECLARE v_try INT;

    DECLARE v_pick_major TINYINT;
    DECLARE v_code BIGINT;
    DECLARE v_credit INT;
    DECLARE v_lecture_id INT;
    DECLARE v_score DECIMAL(2,1);

    -- 0) 초기화
    SET FOREIGN_KEY_CHECKS = 0;
    TRUNCATE TABLE lecture_history;
    SET FOREIGN_KEY_CHECKS = 1;

    -- 1) student.major_id 컬럼 존재 여부 체크 (없으면 student_id로 전공 임의 부여)
    SELECT COUNT(*)
      INTO v_has_student_major
      FROM information_schema.COLUMNS
     WHERE TABLE_SCHEMA = DATABASE()
       AND TABLE_NAME = 'student'
       AND COLUMN_NAME = 'major_id';

    -- 2) 학기 목록(term_list) 만들기: lecture에 존재하는 (year, semester) 기준
    DROP TEMPORARY TABLE IF EXISTS term_list;
    CREATE TEMPORARY TABLE term_list (
        term_no INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
        y INT NOT NULL,
        s INT NOT NULL,
        start_date DATE NOT NULL,
        UNIQUE KEY uq_term (y, s)
    ) ENGINE=Memory;

    SELECT DISTINCT
           CAST(l.lecture_year AS UNSIGNED) AS y,
           l.lecture_semester AS s,
           CASE l.lecture_semester
             WHEN 1 THEN STR_TO_DATE(CONCAT(l.lecture_year, '-03-01'), '%Y-%m-%d')
             WHEN 2 THEN STR_TO_DATE(CONCAT(l.lecture_year, '-09-01'), '%Y-%m-%d')
             ELSE STR_TO_DATE(CONCAT(l.lecture_year, '-01-01'), '%Y-%m-%d')
           END AS start_date
      FROM lecture l
     ORDER BY y, s;

    SELECT COUNT(*) INTO v_term_cnt FROM term_list;

    -- 3) 학생 목록(student_list)
    DROP TEMPORARY TABLE IF EXISTS student_list;
    CREATE TEMPORARY TABLE student_list (
        row_no INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
        student_id INT NOT NULL,
        UNIQUE KEY uq_student (student_id)
    ) ENGINE=Memory;

    SELECT s.student_id
      FROM student s
     ORDER BY s.student_id;

    SELECT COUNT(*) INTO v_student_cnt FROM student_list;

    -- 4) 학생별 생성
    SET i = 1;
    student_loop: WHILE i <= v_student_cnt DO
        SELECT student_id INTO v_student_id
          FROM student_list
         WHERE row_no = i;

        -- 학생 전공
        IF v_has_student_major > 0 THEN
            SELECT major_id INTO v_student_major_id
              FROM student
             WHERE student_id = v_student_id;
            IF v_student_major_id IS NULL THEN
                SET v_student_major_id = (v_student_id MOD 10) + 1;
            END IF;
        ELSE
            SET v_student_major_id = (v_student_id MOD 10) + 1;
        END IF;

        -- 상태 변경 cutoff (휴학/자퇴/퇴학, + 덤프에 '휴학학' 같은 오타도 있어 LIKE 처리)
        SELECT MIN(status_at) INTO v_cutoff_at
          FROM student_status_history
         WHERE student_id = v_student_id
           AND (status_type IN ('자퇴','퇴학') OR status_type LIKE '휴학%');

        IF v_cutoff_at IS NULL THEN
            SET v_cutoff_at = '9999-12-31 00:00:00';
        END IF;

        -- 과거에 3.5 이상 받은 lecture_code 저장(이후 재수강 금지)
        DROP TEMPORARY TABLE IF EXISTS passed_codes;
        CREATE TEMPORARY TABLE passed_codes (
            lecture_code BIGINT NOT NULL PRIMARY KEY
        ) ENGINE=Memory;

        -- 5) 학기별 생성
        SET j = 1;
        term_loop: WHILE j <= v_term_cnt DO
            SELECT y, s, start_date
              INTO v_year, v_sem, v_start_date
              FROM term_list
             WHERE term_no = j;

            -- cutoff 이후 시작 학기면 더 이상 생성하지 않음
            IF v_start_date >= DATE(v_cutoff_at) THEN
                LEAVE term_loop;
            END IF;

            -- 같은 학기 내 중복(lecture_code) 방지
            DROP TEMPORARY TABLE IF EXISTS taken_codes;
            CREATE TEMPORARY TABLE taken_codes (
                lecture_code BIGINT NOT NULL PRIMARY KEY
            ) ENGINE=Memory;

            SET v_credit_sum = 0;
            SET v_try = 0;

            -- 최대 시도 횟수 내에서 랜덤으로 담되, 학점 21 이하로 유지
            pick_loop: WHILE v_try < 80 DO
                -- 70% 전공 우선, 30% 교양/기타
                SET v_pick_major = (RAND() < 0.70);

                SET v_code = NULL;
                SET v_credit = NULL;

                IF v_pick_major = 1 THEN
                    -- 전공 후보(학생 전공 major_id + lecture_type='전공')
                    SELECT t.lecture_code, t.lecture_credit
                      INTO v_code, v_credit
                      FROM (
                            SELECT DISTINCT l.lecture_code, l.lecture_credit
                              FROM lecture l
                             WHERE l.lecture_year = CAST(v_year AS CHAR)
                               AND l.lecture_semester = v_sem
                               AND l.lecture_type = '전공'
                               AND l.major_id = v_student_major_id
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM taken_codes)
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM passed_codes)
                           ) t
                     ORDER BY RAND()
                     LIMIT 1;
                END IF;

                -- 전공에서 못 뽑았으면 교양(또는 전체)로 fallback
                IF v_code IS NULL THEN
                    SELECT t.lecture_code, t.lecture_credit
                      INTO v_code, v_credit
                      FROM (
                            SELECT DISTINCT l.lecture_code, l.lecture_credit
                              FROM lecture l
                             WHERE l.lecture_year = CAST(v_year AS CHAR)
                               AND l.lecture_semester = v_sem
                               AND l.lecture_type = '교양'
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM taken_codes)
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM passed_codes)
                           ) t
                     ORDER BY RAND()
                     LIMIT 1;
                END IF;

                -- 교양도 없으면 전체에서 채움(데이터 부족 방어)
                IF v_code IS NULL THEN
                    SELECT t.lecture_code, t.lecture_credit
                      INTO v_code, v_credit
                      FROM (
                            SELECT DISTINCT l.lecture_code, l.lecture_credit
                              FROM lecture l
                             WHERE l.lecture_year = CAST(v_year AS CHAR)
                               AND l.lecture_semester = v_sem
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM taken_codes)
                               AND l.lecture_code NOT IN (SELECT lecture_code FROM passed_codes)
                           ) t
                     ORDER BY RAND()
                     LIMIT 1;
                END IF;

                -- 더 이상 넣을 게 없으면 종료
                IF v_code IS NULL OR v_credit IS NULL THEN
                    LEAVE pick_loop;
                END IF;

                -- 학점 21 초과 방지
                IF v_credit_sum + v_credit > 21 THEN
                    SET v_try = v_try + 1;
                    ITERATE pick_loop;
                END IF;

                -- 해당 lecture_code의 분반(lecture_id) 중 1개 랜덤 선택
                SELECT l.lecture_id
                  INTO v_lecture_id
                  FROM lecture l
                 WHERE l.lecture_year = CAST(v_year AS CHAR)
                   AND l.lecture_semester = v_sem
                   AND l.lecture_code = v_code
                 ORDER BY RAND()
                 LIMIT 1;

                -- 점수: 0.0 ~ 4.5 (0.5 단위)
                -- 점수 분포: 70%는 2.5~3.5, 30%는 나머지(0.0~2.0, 4.0~4.5)
				-- 0.5 단위 유지
				IF RAND() < 0.70 THEN
				    -- 2.5, 3.0, 3.5 중 하나 (각각 동일 확률)
				    SET v_score = 2.5 + (FLOOR(RAND() * 3) * 0.5);
				ELSE
				    -- 나머지 점수 풀: 0.0,0.5,1.0,1.5,2.0,4.0,4.5 (7개)
				    SET v_score = CASE FLOOR(RAND() * 7)
				        WHEN 0 THEN 0.0
				        WHEN 1 THEN 0.5
				        WHEN 2 THEN 1.0
				        WHEN 3 THEN 1.5
				        WHEN 4 THEN 2.0
				        WHEN 5 THEN 4.0
				        ELSE 4.5
				    END;
				END IF;

                VALUES (v_student_id, v_lecture_id, v_score);


                -- 3.5 이상이면 이후 동일 코드 재수강 금지
                IF v_score >= 3.5 THEN
                END IF;

                SET v_credit_sum = v_credit_sum + v_credit;
                SET v_try = v_try + 1;

                -- 딱 21이면 종료
                IF v_credit_sum = 21 THEN
                    LEAVE pick_loop;
                END IF;
            END WHILE;

            SET j = j + 1;
        END WHILE;

        SET i = i + 1;
    END WHILE;

END $$

DELIMITER ;

-- 실행
CALL insert_lecture_history_dummy_v1();

-- lecture_history 더미 확인용
SELECT Count(*) FROM lecture_history;

-- 수강이력 테이블 총 점수 분포도 확인
SELECT lecture_score, COUNT(*) cnt
FROM lecture_history
GROUP BY lecture_score
ORDER BY lecture_score;

-- 학기별 수강 이력 분포도 확인
SELECT l.lecture_year, l.lecture_semester, COUNT(*) cnt
FROM lecture_history lh
JOIN lecture l ON lh.lecture_id = l.lecture_id
GROUP BY l.lecture_year, l.lecture_semester
ORDER BY l.lecture_year, l.lecture_semester;

-- 학생 상태 '재학' 아닌 이후 수강 이력 있는지 확인
WITH cutoff AS (
  SELECT student_id, MIN(status_at) AS cutoff_at
  FROM student_status_history
  WHERE (status_type IN ('자퇴','퇴학') OR status_type LIKE '휴학%')
  GROUP BY student_id
),
term_start AS (
  SELECT lecture_id,
         CASE lecture_semester
           WHEN 1 THEN STR_TO_DATE(CONCAT(lecture_year,'-03-01'),'%Y-%m-%d')
           WHEN 2 THEN STR_TO_DATE(CONCAT(lecture_year,'-09-01'),'%Y-%m-%d')
         END AS start_date
  FROM lecture
)
SELECT lh.student_id, lh.lecture_id, c.cutoff_at, ts.start_date
FROM lecture_history lh
JOIN cutoff c ON c.student_id = lh.student_id
JOIN term_start ts ON ts.lecture_id = lh.lecture_id
WHERE ts.start_date >= DATE(c.cutoff_at);

-- 3.5 이상인 학생이 같은 강의코드 재수강 했는지 확인
WITH t AS (
  SELECT lh.student_id, l.lecture_code,
         (CAST(l.lecture_year AS UNSIGNED)*10 + l.lecture_semester) AS term_key,
         lh.lecture_score
  FROM lecture_history lh
  JOIN lecture l ON lh.lecture_id = l.lecture_id
),
first_pass AS (
  SELECT student_id, lecture_code, MIN(term_key) AS first_pass_term
  FROM t
  WHERE lecture_score >= 3.5
  GROUP BY student_id, lecture_code
)
SELECT t.student_id, t.lecture_code, t.term_key, t.lecture_score, fp.first_pass_term
FROM t
JOIN first_pass fp
  ON fp.student_id = t.student_id AND fp.lecture_code = t.lecture_code
WHERE t.term_key > fp.first_pass_term;

-- 분반 수강 했는지 확인
SELECT lh.student_id, l.lecture_year, l.lecture_semester, l.lecture_code,
       COUNT(*) AS cnt
FROM lecture_history lh
JOIN lecture l ON lh.lecture_id = l.lecture_id
GROUP BY lh.student_id, l.lecture_year, l.lecture_semester, l.lecture_code
HAVING COUNT(*) > 1;

-- 한 학기당 최대학점(21점) 넘어서 수강하는 거 있는지 확인
SELECT lh.student_id, l.lecture_year, l.lecture_semester,
       SUM(l.lecture_credit) AS total_credits
FROM lecture_history lh
JOIN lecture l ON lh.lecture_id = l.lecture_id
GROUP BY lh.student_id, l.lecture_year, l.lecture_semester
HAVING SUM(l.lecture_credit) > 21;